aqI(a){return"Supprimer votre partie de "+a+" ? Elle dispara\xeet pour tout le monde, avec ce qui y a \xe9t\xe9 enregistr\xe9."},
gaqy(){return"Plus"},
gaqu(){return"Pr\xe9sent"},
